[metadata] {"type": "create", "filePath": "/app/output/index.html", "content": "<!DOCTYPE html>
<html lang="en">
<head>
  <meta charset="UTF-8" />
  <meta name="viewport" content="width=device-width, initial-scale=1.0" />
  <title>Global Aid Alliance — Together We Respond</title>
  <meta name="description" content="A humanitarian nonprofit organization dedicated to disaster relief, emergency assistance, and community resilience worldwide." />
  <link rel="preconnect" href="https://fonts.googleapis.com" />
  <link rel="preconnect" href="https://fonts.gstatic.com" crossorigin />
  <link href="https://fonts.googleapis.com/css2?family=Inter:wght@400;500;600;700;800;900&family=Source+Serif+4:ital,wght@0,400;0,600;1,400&display=swap" rel="stylesheet" />
  <style>
    /* ─── Reset & Base ─────────────────────────────────────────── */
    *, *::before, *::after { box-sizing: border-box; margin: 0; padding: 0; }
    html { scroll-behavior: smooth; font-size: 16px; }
    body {
      font-family: 'Inter', sans-serif;
      color: #1a1a1a;
      background: #ffffff;
      line-height: 1.6;
      -webkit-font-smoothing: antialiased;
    }
    img { display: block; max-width: 100%; }
    a { text-decoration: none; color: inherit; }
    button { font-family: inherit; cursor: pointer; border: none; background: none; }
    ul { list-style: none; }

    /* ─── Design Tokens ────────────────────────────────────────── */
    :root {
      --red: #C41E3A;
      --red-dark: #a01830;
      --red-light: #f8e8eb;
      --navy: #1B3A5C;
      --navy-dark: #122843;
      --navy-light: #e8edf3;
      --white: #ffffff;
      --gray-50: #f9fafb;
      --gray-100: #f3f4f6;
      --gray-200: #e5e7eb;
      --gray-300: #d1d5db;
      --gray-400: #9ca3af;
      --gray-500: #6b7280;
      --gray-600: #4b5563;
      --gray-700: #374151;
      --gray-800: #1f2937;
      --gray-900: #111827;
      --shadow-sm: 0 1px 2px rgba(0,0,0,0.05);
      --shadow: 0 4px 6px -1px rgba(0,0,0,0.1), 0 2px 4px -1px rgba(0,0,0,0.06);
      --shadow-md: 0 10px 15px -3px rgba(0,0,0,0.1), 0 4px 6px -2px rgba(0,0,0,0.05);
      --shadow-lg: 0 20px 25px -5px rgba(0,0,0,0.1), 0 10px 10px -5px rgba(0,0,0,0.04);
      --radius: 8px;
      --radius-lg: 12px;
      --transition: 200ms cubic-bezier(0.4, 0, 0.2, 1);
    }

    /* ─── Utility ──────────────────────────────────────────────── */
    .container { width: 100%; max-width: 1200px; margin: 0 auto; padding: 0 24px; }
    .sr-only { position: absolute; width: 1px; height: 1px; padding: 0; margin: -1px; overflow: hidden; clip: rect(0,0,0,0); white-space: nowrap; border: 0; }

    .btn {
      display: inline-flex; align-items: center; justify-content: center; gap: 8px;
      padding: 12px 28px; border-radius: var(--radius); font-weight: 600; font-size: 15px;
      transition: all var(--transition); white-space: nowrap; letter-spacing: 0.01em;
    }
    .btn-primary { background: var(--red); color: #fff; }
    .btn-primary:hover { background: var(--red-dark); transform: translateY(-1px); box-shadow: 0 4px 12px rgba(196,30,58,0.35); }
    .btn-secondary { background: transparent; color: #fff; border: 2px solid rgba(255,255,255,0.8); }
    .btn-secondary:hover { background: rgba(255,255,255,0.15); }
    .btn-outline-red { background: transparent; color: var(--red); border: 2px solid var(--red); }
    .btn-outline-red:hover { background: var(--red); color: #fff; }
    .btn-navy { background: var(--navy); color: #fff; }
    .btn-navy:hover { background: var(--navy-dark); transform: translateY(-1px); box-shadow: 0 4px 12px rgba(27,58,92,0.35); }
    .btn-lg { padding: 15px 36px; font-size: 17px; }

    /* ─── Top Utility Bar ──────────────────────────────────────── */
    .utility-bar {
      background: var(--navy);
      color: rgba(255,255,255,0.85);
      font-size: 13px;
      padding: 6px 0;
    }
    .utility-bar .container {
      display: flex; justify-content: flex-end; align-items: center; gap: 20px;
    }
    .utility-bar a { color: rgba(255,255,255,0.8); transition: color var(--transition); }
    .utility-bar a:hover { color: #fff; }
    .utility-bar .separator { color: rgba(255,255,255,0.3); }

    /* ─── Header ───────────────────────────────────────────────── */
    .site-header {
      position: sticky; top: 0; z-index: 100;
      background: #fff;
      box-shadow: 0 1px 0 var(--gray-200), var(--shadow-sm);
      transition: box-shadow var(--transition);
    }
    .site-header.scrolled { box-shadow: var(--shadow-md); }
    .header-inner {
      display: flex; align-items: center; justify-content: space-between;
      padding: 16px 24px; max-width: 1200px; margin: 0 auto;
    }
    .logo { display: flex; align-items: center; gap: 10px; }
    .logo-icon {
      width: 44px; height: 44px; background: var(--red); border-radius: 50%;
      display: flex; align-items: center; justify-content: center; flex-shrink: 0;
    }
    .logo-cross {
      width: 22px; height: 22px; position: relative;
    }
    .logo-cross::before,
    .logo-cross::after {
      content: ''; position: absolute; background: #fff; border-radius: 2px;
    }
    .logo-cross::before { width: 4px; height: 22px; left: 9px; top: 0; }
    .logo-cross::after { width: 22px; height: 4px; left: 0; top: 9px; }
    .logo-text { line-height: 1.2; }
    .logo-text strong { display: block; font-size: 15px; font-weight: 800; color: var(--gray-900); letter-spacing: -0.01em; }
    .logo-text span { font-size: 11px; color: var(--gray-500); font-weight: 500; text-transform: uppercase; letter-spacing: 0.05em; }

    .main-nav { display: flex; align-items: center; gap: 4px; }
    .main-nav a {
      padding: 8px 14px; font-size: 14px; font-weight: 500; color: var(--gray-700);
      border-radius: var(--radius); transition: all var(--transition);
    }
    .main-nav a:hover { color: var(--gray-900); background: var(--gray-100); }
    .nav-donate { background: var(--red) !important; color: #fff !important; font-weight: 600 !important; }
    .nav-donate:hover { background: var(--red-dark) !important; box-shadow: 0 2px 8px rgba(196,30,58,0.3); }

    .hamburger {
      display: none; flex-direction: column; gap: 5px;
      padding: 8px; border-radius: var(--radius); transition: background var(--transition);
      background: none; border: none; cursor: pointer;
    }
    .hamburger:hover { background: var(--gray-100); }
    .hamburger span {
      display: block; width: 22px; height: 2px; background: var(--gray-700);
      border-radius: 2px; transition: all 300ms ease;
    }
    .hamburger.open span:nth-child(1) { transform: translateY(7px) rotate(45deg); }
    .hamburger.open span:nth-child(2) { opacity: 0; transform: scaleX(0); }
    .hamburger.open span:nth-child(3) { transform: translateY(-7px) rotate(-45deg); }

    .mobile-nav {
      display: none; position: fixed; top: 0; left: 0; right: 0; bottom: 0;
      background: #fff; z-index: 99; padding: 80px 24px 40px; overflow-y: auto;
      transform: translateX(-100%); transition: transform 350ms cubic-bezier(0.4, 0, 0.2, 1);
    }
    .mobile-nav.open { transform: translateX(0); }
    .mobile-nav-links { display: flex; flex-direction: column; gap: 4px; }
    .mobile-nav-links a {
      display: block; padding: 14px 16px; font-size: 17px; font-weight: 500;
      color: var(--gray-800); border-radius: var(--radius);
      border-bottom: 1px solid var(--gray-100); transition: all var(--transition);
    }
    .mobile-nav-links a:hover { background: var(--gray-50); color: var(--red); }
    .mobile-nav-donate {
      margin-top: 24px; width: 100%; text-align: center;
    }

    /* ─── Hero ─────────────────────────────────────────────────── */
    .hero {
      position: relative; min-height: 88vh;
      display: flex; align-items: center;
      background: linear-gradient(135deg, var(--navy-dark) 0%, var(--navy) 40%, #2a4f78 70%, #1a3550 100%);
      overflow: hidden;
    }
    .hero-bg-pattern {
      position: absolute; inset: 0;
      background-image:
        radial-gradient(circle at 20% 50%, rgba(196,30,58,0.12) 0%, transparent 50%),
        radial-gradient(circle at 80% 20%, rgba(255,255,255,0.04) 0%, transparent 40%),
        url("data:image/svg+xml,%3Csvg width='60' height='60' viewBox='0 0 60 60' xmlns='http://www.w3.org/2000/svg'%3E%3Cg fill='none' fill-rule='evenodd'%3E%3Cg fill='%23ffffff' fill-opacity='0.02'%3E%3Cpath d='M36 34v-4h-2v4h-4v2h4v4h2v-4h4v-2h-4zm0-30V0h-2v4h-4v2h4v4h2V6h4V4h-4zM6 34v-4H4v4H0v2h4v4h2v-4h4v-2H6zM6 4V0H4v4H0v2h4v4h2V6h4V4H6z'/%3E%3C/g%3E%3C/g%3E%3C/svg%3E");
    }
    .hero-accent {
      position: absolute; right: 0; top: 0; bottom: 0; width: 45%;
      background: url('https://images.unsplash.com/photo-1469571486292-0ba58a3f068b?w=800&q=80') center/cover no-repeat;
      opacity: 0.18;
      clip-path: polygon(10% 0, 100% 0, 100% 100%, 0% 100%);
    }
    .hero-red-bar {
      position: absolute; left: 0; top: 0; bottom: 0; width: 6px;
      background: var(--red);
    }
    .hero-content {
      position: relative; z-index: 2;
      padding: 80px 0;
    }
    .hero-eyebrow {
      display: inline-flex; align-items: center; gap: 8px;
      background: rgba(196,30,58,0.2); border: 1px solid rgba(196,30,58,0.4);
      color: #f9a0b0; padding: 6px 14px; border-radius: 100px;
      font-size: 12px; font-weight: 600; letter-spacing: 0.08em; text-transform: uppercase;
      margin-bottom: 24px;
    }
    .hero-eyebrow-dot { width: 6px; height: 6px; background: var(--red); border-radius: 50%; animation: pulse 2s infinite; }
    @keyframes pulse { 0%, 100% { opacity: 1; transform: scale(1); } 50% { opacity: 0.5; transform: scale(1.3); } }
    .hero h1 {
      font-size: clamp(36px, 5vw, 68px); font-weight: 900;
      color: #fff; line-height: 1.08; letter-spacing: -0.025em;
      max-width: 700px; margin-bottom: 24px;
    }
    .hero h1 span { color: #f9a0b0; }
    .hero-subtitle {
      font-size: clamp(16px, 2vw, 20px); color: rgba(255,255,255,0.78);
      max-width: 560px; margin-bottom: 40px; line-height: 1.7;
    }
    .hero-actions { display: flex; gap: 16px; flex-wrap: wrap; }
    .hero-trust {
      margin-top: 64px; padding-top: 32px;
      border-top: 1px solid rgba(255,255,255,0.1);
      display: flex; align-items: center; gap: 32px; flex-wrap: wrap;
    }
    .hero-trust-item { text-align: center; }
    .hero-trust-item strong { display: block; font-size: 26px; font-weight: 800; color: #fff; letter-spacing: -0.02em; }
    .hero-trust-item span { font-size: 12px; color: rgba(255,255,255,0.6); text-transform: uppercase; letter-spacing: 0.06em; font-weight: 500; }
    .hero-trust-divider { width: 1px; height: 40px; background: rgba(255,255,255,0.15); }

    /* ─── Section Common ───────────────────────────────────────── */
    .section { padding: 96px 0; }
    .section-alt { background: var(--gray-50); }
    .section-dark { background: var(--navy); color: #fff; }
    .section-header { text-align: center; max-width: 640px; margin: 0 auto 60px; }
    .section-label {
      display: inline-block; font-size: 12px; font-weight: 700; letter-spacing: 0.1em;
      text-transform: uppercase; color: var(--red); margin-bottom: 12px;
    }
    .section-dark .section-label { color: #f9a0b0; }
    .section-title {
      font-size: clamp(28px, 3.5vw, 42px); font-weight: 800;
      color: var(--gray-900); letter-spacing: -0.025em; line-height: 1.15;
      margin-bottom: 16px;
    }
    .section-dark .section-title { color: #fff; }
    .section-subtitle { font-size: 17px; color: var(--gray-600); line-height: 1.7; }
    .section-dark .section-subtitle { color: rgba(255,255,255,0.7); }

    /* ─── Mission ──────────────────────────────────────────────── */
    .mission-grid {
      display: grid; grid-template-columns: 1fr 1fr; gap: 64px; align-items: center;
    }
    .mission-image {
      position: relative; border-radius: var(--radius-lg); overflow: hidden;
      aspect-ratio: 4/3; background: var(--gray-200);
    }
    .mission-image img { width: 100%; height: 100%; object-fit: cover; }
    .mission-image-overlay {
      position: absolute; inset: 0;
      background: linear-gradient(to top, rgba(27,58,92,0.5) 0%, transparent 60%);
    }
    .mission-image-badge {
      position: absolute; bottom: 24px; left: 24px;
      background: var(--red); color: #fff;
      padding: 10px 16px; border-radius: var(--radius); font-weight: 700; font-size: 13px;
    }
    .mission-content .section-header { text-align: left; margin: 0 0 32px; }
    .mission-principles { display: flex; flex-direction: column; gap: 16px; margin-top: 32px; }
    .principle {
      display: flex; gap: 16px; align-items: flex-start;
      padding: 16px; background: var(--gray-50); border-radius: var(--radius);
      border-left: 3px solid var(--red);
    }
    .principle-icon {
      width: 36px; height: 36px; background: var(--red-light); border-radius: 50%;
      display: flex; align-items: center; justify-content: center; flex-shrink: 0; font-size: 16px;
    }
    .principle-text strong { display: block; font-size: 14px; font-weight: 700; color: var(--gray-900); margin-bottom: 2px; }
    .principle-text span { font-size: 13px; color: var(--gray-600); }

    /* ─── Impact Stats ─────────────────────────────────────────── */
    .stats-section { background: var(--navy); }
    .stats-grid {
      display: grid; grid-template-columns: repeat(4, 1fr); gap: 2px;
      background: rgba(255,255,255,0.08); border-radius: var(--radius-lg); overflow: hidden;
    }
    .stat-card {
      background: rgba(255,255,255,0.04); padding: 48px 32px; text-align: center;
      transition: background var(--transition); position: relative; overflow: hidden;
    }
    .stat-card::before {
      content: ''; position: absolute; top: 0; left: 50%; transform: translateX(-50%);
      width: 60px; height: 3px; background: var(--red);
    }
    .stat-card:hover { background: rgba(255,255,255,0.08); }
    .stat-number {
      display: block; font-size: clamp(36px, 4vw, 56px); font-weight: 900;
      color: #fff; letter-spacing: -0.03em; line-height: 1; margin-bottom: 12px;
    }
    .stat-number span { color: var(--red); }
    .stat-label { font-size: 14px; color: rgba(255,255,255,0.65); font-weight: 500; text-transform: uppercase; letter-spacing: 0.06em; }
    .stat-description { font-size: 13px; color: rgba(255,255,255,0.45); margin-top: 6px; }

    /* ─── Programs Accordion ───────────────────────────────────── */
    .programs-layout { display: grid; grid-template-columns: 1fr 1fr; gap: 48px; align-items: start; }
    .programs-intro { position: sticky; top: 100px; }
    .programs-intro .section-header { text-align: left; margin: 0; }
    .programs-intro p { color: var(--gray-600); line-height: 1.7; margin-top: 16px; font-size: 16px; }

    .accordion { display: flex; flex-direction: column; gap: 8px; }
    .accordion-item {
      border: 1px solid var(--gray-200); border-radius: var(--radius-lg);
      overflow: hidden; transition: border-color var(--transition), box-shadow var(--transition);
    }
    .accordion-item.open { border-color: var(--red); box-shadow: 0 0 0 3px var(--red-light); }
    .accordion-trigger {
      width: 100%; display: flex; align-items: center; justify-content: space-between;
      padding: 20px 24px; text-align: left; background: #fff;
      transition: background var(--transition); cursor: pointer; border: none; font-family: inherit;
    }
    .accordion-trigger:hover { background: var(--gray-50); }
    .accordion-item.open .accordion-trigger { background: var(--red-light); }
    .accordion-trigger-content { display: flex; align-items: center; gap: 14px; }
    .accordion-icon {
      width: 40px; height: 40px; border-radius: 10px; background: var(--gray-100);
      display: flex; align-items: center; justify-content: center; font-size: 18px; flex-shrink: 0;
      transition: background var(--transition);
    }
    .accordion-item.open .accordion-icon { background: var(--red); }
    .accordion-title { font-size: 16px; font-weight: 700; color: var(--gray-900); }
    .accordion-chevron {
      width: 20px; height: 20px; color: var(--gray-400); flex-shrink: 0;
      transition: transform 300ms ease;
    }
    .accordion-item.open .accordion-chevron { transform: rotate(180deg); color: var(--red); }
    .accordion-body {
      max-height: 0; overflow: hidden;
      transition: max-height 350ms cubic-bezier(0.4, 0, 0.2, 1);
    }
    .accordion-body-inner { padding: 0 24px 24px; }
    .accordion-body p { color: var(--gray-600); font-size: 15px; line-height: 1.7; margin-bottom: 16px; }
    .accordion-body a { color: var(--red); font-weight: 600; font-size: 14px; }
    .accordion-body a:hover { text-decoration: underline; }

    /* ─── Get Involved ─────────────────────────────────────────── */
    .involved-grid { display: grid; grid-template-columns: repeat(3, 1fr); gap: 32px; }
    .involved-card {
      background: #fff; border-radius: var(--radius-lg); overflow: hidden;
      border: 1px solid var(--gray-200); transition: all var(--transition);
    }
    .involved-card:hover { transform: translateY(-4px); box-shadow: var(--shadow-lg); border-color: transparent; }
    .involved-card-image {
      height: 200px; background: var(--gray-200); overflow: hidden; position: relative;
    }
    .involved-card-image img { width: 100%; height: 100%; object-fit: cover; transition: transform 400ms ease; }
    .involved-card:hover .involved-card-image img { transform: scale(1.05); }
    .involved-card-image-overlay {
      position: absolute; inset: 0;
      background: linear-gradient(to top, rgba(27,58,92,0.6) 0%, transparent 50%);
    }
    .involved-card-body { padding: 28px; }
    .involved-card-icon { font-size: 28px; margin-bottom: 12px; }
    .involved-card h3 { font-size: 20px; font-weight: 800; color: var(--gray-900); margin-bottom: 10px; }
    .involved-card p { color: var(--gray-600); font-size: 14px; line-height: 1.7; margin-bottom: 20px; }

    /* ─── News Carousel ────────────────────────────────────────── */
    .news-section { background: var(--gray-50); }
    .news-controls {
      display: flex; align-items: center; gap: 8px;
    }
    .news-header-row {
      display: flex; align-items: flex-end; justify-content: space-between;
      margin-bottom: 40px; flex-wrap: wrap; gap: 24px;
    }
    .news-header-row .section-header { text-align: left; margin: 0; }
    .carousel-btn {
      width: 44px; height: 44px; border-radius: 50%; border: 2px solid var(--gray-300);
      display: flex; align-items: center; justify-content: center; color: var(--gray-600);
      transition: all var(--transition); background: #fff; cursor: pointer;
    }
    .carousel-btn:hover { border-color: var(--red); color: var(--red); background: var(--red-light); }
    .carousel-btn:disabled { opacity: 0.4; cursor: not-allowed; }
    .carousel-btn svg { width: 18px; height: 18px; }

    .news-track-wrapper { overflow: hidden; border-radius: var(--radius-lg); }
    .news-track {
      display: flex; gap: 24px;
      transition: transform 400ms cubic-bezier(0.4, 0, 0.2, 1);
    }
    .news-card {
      flex: 0 0 calc(33.333% - 16px); background: #fff; border-radius: var(--radius-lg);
      overflow: hidden; border: 1px solid var(--gray-200);
      transition: all var(--transition); min-width: 0;
    }
    .news-card:hover { box-shadow: var(--shadow-md); border-color: transparent; }
    .news-card-image {
      height: 200px; background: var(--gray-200); overflow: hidden;
    }
    .news-card-image img { width: 100%; height: 100%; object-fit: cover; transition: transform 400ms ease; }
    .news-card:hover .news-card-image img { transform: scale(1.05); }
    .news-card-body { padding: 24px; }
    .news-tag {
      display: inline-block; padding: 4px 10px; border-radius: 100px;
      font-size: 11px; font-weight: 700; letter-spacing: 0.05em; text-transform: uppercase;
      background: var(--red-light); color: var(--red); margin-bottom: 12px;
    }
    .news-tag.blue { background: var(--navy-light); color: var(--navy); }
    .news-card h3 { font-size: 17px; font-weight: 700; color: var(--gray-900); line-height: 1.4; margin-bottom: 10px; }
    .news-card p { font-size: 14px; color: var(--gray-600); line-height: 1.6; margin-bottom: 16px; }
    .news-card-meta { display: flex; align-items: center; gap: 8px; }
    .news-date { font-size: 12px; color: var(--gray-400); font-weight: 500; }
    .news-read-more { font-size: 13px; color: var(--red); font-weight: 600; margin-left: auto; }
    .news-read-more:hover { text-decoration: underline; }
    .carousel-dots { display: flex; justify-content: center; gap: 8px; margin-top: 32px; }
    .carousel-dot {
      width: 8px; height: 8px; border-radius: 50%; background: var(--gray-300);
      transition: all var(--transition); cursor: pointer; border: none;
    }
    .carousel-dot.active { background: var(--red); width: 24px; border-radius: 4px; }

    /* ─── Donate CTA ───────────────────────────────────────────── */
    .donate-section {
      background: linear-gradient(135deg, var(--red-dark) 0%, var(--red) 50%, #d4415a 100%);
      position: relative; overflow: hidden;
    }
    .donate-section::before {
      content: ''; position: absolute; inset: 0;
      background: url("data:image/svg+xml,%3Csvg width='80' height='80' viewBox='0 0 80 80' xmlns='http://www.w3.org/2000/svg'%3E%3Cg fill='none' fill-rule='evenodd'%3E%3Cg fill='%23ffffff' fill-opacity='0.04'%3E%3Ccircle cx='40' cy='40' r='20'/%3E%3C/g%3E%3C/g%3E%3C/svg%3E");
    }
    .donate-inner {
      position: relative; z-index: 1;
      display: grid; grid-template-columns: 1fr 1fr; gap: 80px; align-items: center;
    }
    .donate-content .section-header { text-align: left; margin: 0 0 24px; }
    .donate-stat {
      display: inline-flex; align-items: center; gap: 8px; margin-bottom: 24px;
      background: rgba(255,255,255,0.15); padding: 8px 16px; border-radius: 100px;
    }
    .donate-stat-icon { font-size: 18px; }
    .donate-stat span { font-size: 14px; color: rgba(255,255,255,0.9); font-weight: 600; }
    .donate-amounts {
      display: flex; flex-direction: column; gap: 16px;
      background: rgba(255,255,255,0.1); border-radius: var(--radius-lg); padding: 28px;
      backdrop-filter: blur(8px); border: 1px solid rgba(255,255,255,0.2);
    }
    .donate-amounts h3 { color: #fff; font-size: 18px; font-weight: 700; margin-bottom: 8px; }
    .amount-grid { display: grid; grid-template-columns: repeat(3, 1fr); gap: 10px; margin-bottom: 12px; }
    .amount-btn {
      padding: 12px 8px; background: rgba(255,255,255,0.15); border: 2px solid rgba(255,255,255,0.25);
      border-radius: var(--radius); color: #fff; font-size: 16px; font-weight: 700;
      cursor: pointer; transition: all var(--transition); font-family: inherit;
    }
    .amount-btn:hover, .amount-btn.selected { background: #fff; color: var(--red); border-color: #fff; }
    .donate-cta-btn {
      width: 100%; padding: 16px; background: #fff; color: var(--red);
      border-radius: var(--radius); font-size: 17px; font-weight: 800;
      cursor: pointer; border: none; font-family: inherit;
      transition: all var(--transition); letter-spacing: 0.01em;
    }
    .donate-cta-btn:hover { background: var(--gray-100); transform: translateY(-1px); box-shadow: 0 4px 16px rgba(0,0,0,0.2); }
    .donate-note { font-size: 12px; color: rgba(255,255,255,0.6); text-align: center; margin-top: 10px; }

    /* ─── Footer ───────────────────────────────────────────────── */
    .site-footer { background: var(--gray-900); color: rgba(255,255,255,0.75); }
    .footer-main { padding: 64px 0 48px; }
    .footer-grid { display: grid; grid-template-columns: 2fr 1fr 1fr 1fr 1fr; gap: 40px; }
    .footer-brand { grid-column: 1; }
    .footer-logo { display: flex; align-items: center; gap: 10px; margin-bottom: 16px; }
    .footer-logo-icon {
      width: 40px; height: 40px; background: var(--red); border-radius: 50%;
      display: flex; align-items: center; justify-content: center; flex-shrink: 0;
    }
    .footer-logo-text strong { display: block; font-size: 14px; font-weight: 800; color: #fff; }
    .footer-logo-text span { font-size: 11px; color: rgba(255,255,255,0.5); }
    .footer-brand p { font-size: 14px; line-height: 1.7; margin-bottom: 24px; max-width: 280px; }
    .footer-social { display: flex; gap: 10px; }
    .social-link {
      width: 36px; height: 36px; border-radius: 8px; background: rgba(255,255,255,0.08);
      display: flex; align-items: center; justify-content: center; font-size: 14px;
      transition: all var(--transition); color: rgba(255,255,255,0.6);
    }
    .social-link:hover { background: var(--red); color: #fff; }
    .footer-col h4 { font-size: 12px; font-weight: 700; color: #fff; text-transform: uppercase; letter-spacing: 0.08em; margin-bottom: 16px; }
    .footer-col ul { display: flex; flex-direction: column; gap: 10px; }
    .footer-col ul a { font-size: 14px; color: rgba(255,255,255,0.6); transition: color var(--transition); }
    .footer-col ul a:hover { color: #fff; }
    .footer-bottom {
      border-top: 1px solid rgba(255,255,255,0.08); padding: 24px 0;
      display: flex; align-items: center; justify-content: space-between; flex-wrap: wrap; gap: 16px;
    }
    .footer-bottom p { font-size: 13px; color: rgba(255,255,255,0.4); }
    .footer-badges { display: flex; gap: 12px; align-items: center; }
    .footer-badge {
      padding: 4px 12px; border-radius: 100px; font-size: 11px; font-weight: 700;
      background: rgba(255,255,255,0.08); color: rgba(255,255,255,0.5); letter-spacing: 0.04em;
    }

    /* ─── Donation Modal ───────────────────────────────────────── */
    .modal-overlay {
      position: fixed; inset: 0; z-index: 1000;
      background: rgba(0,0,0,0.7); backdrop-filter: blur(4px);
      display: flex; align-items: center; justify-content: center; padding: 24px;
      opacity: 0; pointer-events: none; transition: opacity 300ms ease;
    }
    .modal-overlay.open { opacity: 1; pointer-events: all; }
    .modal {
      background: #fff; border-radius: var(--radius-lg); max-width: 560px; width: 100%;
      overflow: hidden; box-shadow: var(--shadow-lg);
      transform: translateY(20px) scale(0.97); transition: transform 300ms ease;
      max-height: 90vh; overflow-y: auto;
    }
    .modal-overlay.open .modal { transform: translateY(0) scale(1); }
    .modal-header {
      background: linear-gradient(135deg, var(--red-dark), var(--red));
      padding: 28px 32px; position: relative; color: #fff;
    }
    .modal-header h2 { font-size: 24px; font-weight: 800; margin-bottom: 4px; }
    .modal-header p { font-size: 14px; color: rgba(255,255,255,0.8); }
    .modal-close {
      position: absolute; top: 20px; right: 20px;
      width: 32px; height: 32px; border-radius: 50%;
      background: rgba(255,255,255,0.2); color: #fff; display: flex;
      align-items: center; justify-content: center; cursor: pointer;
      transition: background var(--transition); border: none; font-size: 18px; line-height: 1;
      font-family: inherit;
    }
    .modal-close:hover { background: rgba(255,255,255,0.35); }
    .modal-body { padding: 32px; }
    .modal-frequency { display: flex; gap: 0; margin-bottom: 24px; border: 1px solid var(--gray-200); border-radius: var(--radius); overflow: hidden; }
    .freq-btn {
      flex: 1; padding: 10px; text-align: center; font-size: 14px; font-weight: 600;
      color: var(--gray-600); background: #fff; cursor: pointer; border: none; font-family: inherit;
      transition: all var(--transition);
    }
    .freq-btn.active { background: var(--navy); color: #fff; }
    .modal-amount-label { font-size: 13px; font-weight: 700; color: var(--gray-700); text-transform: uppercase; letter-spacing: 0.06em; margin-bottom: 12px; }
    .modal-amounts { display: grid; grid-template-columns: repeat(3, 1fr); gap: 10px; margin-bottom: 20px; }
    .modal-amount-btn {
      padding: 14px 8px; border: 2px solid var(--gray-200); border-radius: var(--radius);
      background: #fff; cursor: pointer; text-align: center; transition: all var(--transition);
      font-family: inherit;
    }
    .modal-amount-btn:hover { border-color: var(--red); background: var(--red-light); }
    .modal-amount-btn.selected { border-color: var(--red); background: var(--red); }
    .modal-amount-btn.selected .amount-price { color: #fff; }
    .modal-amount-btn.selected .amount-desc { color: rgba(255,255,255,0.8); }
    .amount-price { display: block; font-size: 20px; font-weight: 800; color: var(--gray-900); }
    .amount-desc { display: block; font-size: 11px; color: var(--gray-500); margin-top: 4px; line-height: 1.3; }
    .modal-custom { margin-bottom: 24px; }
    .modal-custom label { display: block; font-size: 13px; font-weight: 700; color: var(--gray-700); text-transform: uppercase; letter-spacing: 0.06em; margin-bottom: 8px; }
    .modal-custom-input {
      display: flex; border: 2px solid var(--gray-200); border-radius: var(--radius);
      overflow: hidden; transition: border-color var(--transition);
    }
    .modal-custom-input:focus-within { border-color: var(--red); }
    .currency-symbol { padding: 12px 14px; background: var(--gray-50); color: var(--gray-500); font-weight: 700; font-size: 15px; border-right: 1px solid var(--gray-200); }
    .modal-custom-input input {
      flex: 1; padding: 12px 14px; border: none; outline: none; font-size: 16px;
      font-family: inherit; font-weight: 600; color: var(--gray-900);
    }
    .modal-impact {
      background: var(--gray-50); border-radius: var(--radius); padding: 14px 16px;
      display: flex; align-items: center; gap: 12px; margin-bottom: 24px;
    }
    .impact-icon { font-size: 24px; }
    .impact-text { font-size: 14px; color: var(--gray-700); font-weight: 500; }
    .modal-submit {
      width: 100%; padding: 16px; background: var(--red); color: #fff;
      border: none; border-radius: var(--radius); font-size: 17px; font-weight: 700;
      cursor: pointer; font-family: inherit; transition: all var(--transition);
    }
    .modal-submit:hover { background: var(--red-dark); transform: translateY(-1px); box-shadow: 0 4px 12px rgba(196,30,58,0.35); }
    .modal-footer-note { text-align: center; font-size: 12px; color: var(--gray-400); margin-top: 14px; }
    .modal-footer-note a { color: var(--gray-600); text-decoration: underline; }

    /* ─── Responsive ───────────────────────────────────────────── */
    @media (max-width: 1024px) {
      .stats-grid { grid-template-columns: repeat(2, 1fr); }
      .programs-layout { grid-template-columns: 1fr; }
      .programs-intro { position: static; }
      .footer-grid { grid-template-columns: 1fr 1fr; }
      .footer-brand { grid-column: span 2; }
    }
    @media (max-width: 768px) {
      .section { padding: 64px 0; }
      .main-nav { display: none; }
      .hamburger { display: flex; }
      .mobile-nav { display: block; }
      .hero { min-height: 75vh; }
      .hero-trust { gap: 20px; }
      .hero-trust-divider { display: none; }
      .mission-grid { grid-template-columns: 1fr; gap: 40px; }
      .mission-image { aspect-ratio: 16/9; }
      .involved-grid { grid-template-columns: 1fr; gap: 24px; }
      .donate-inner { grid-template-columns: 1fr; gap: 40px; }
      .footer-grid { grid-template-columns: 1fr 1fr; gap: 32px; }
      .footer-brand { grid-column: span 2; }
      .news-card { flex: 0 0 calc(100% - 0px); }
      .modal-amounts { grid-template-columns: repeat(2, 1fr); }
    }
    @media (max-width: 480px) {
      .container { padding: 0 16px; }
      .hero h1 { font-size: 30px; }
      .hero-actions { flex-direction: column; }
      .hero-actions .btn { width: 100%; justify-content: center; }
      .stats-grid { grid-template-columns: 1fr 1fr; }
      .amount-grid { grid-template-columns: repeat(2, 1fr); }
      .footer-grid { grid-template-columns: 1fr; }
      .footer-brand { grid-column: span 1; }
      .footer-bottom { flex-direction: column; align-items: flex-start; gap: 12px; }
    }

    /* ─── Counter animation ────────────────────────────────────── */
    .stat-number { transition: none; }
    @keyframes countUp { from { opacity: 0; transform: translateY(10px); } to { opacity: 1; transform: translateY(0); } }
    .stat-card.animated .stat-number { animation: countUp 0.6s ease forwards; }
  </style>
</head>
