<!-- ═══════════════════════════════════════════
     JAVASCRIPT
════════════════════════════════════════════ -->
<script>
  /* ── Header scroll ── */
  const header = document.getElementById('site-header');
  window.addEventListener('scroll', () => {
    header.classList.toggle('scrolled', window.scrollY > 20);
  }, { passive: true });

  /* ── Mobile Nav ── */
  const hamburger = document.getElementById('hamburger');
  const mobileNav = document.getElementById('mobile-nav');
  let mobileNavOpen = false;

  hamburger.addEventListener('click', () => {
    mobileNavOpen = !mobileNavOpen;
    hamburger.classList.toggle('open', mobileNavOpen);
    mobileNav.classList.toggle('open', mobileNavOpen);
    hamburger.setAttribute('aria-expanded', String(mobileNavOpen));
    document.body.style.overflow = mobileNavOpen ? 'hidden' : '';
  });

  function closeMobileNav() {
    mobileNavOpen = false;
    hamburger.classList.remove('open');
    mobileNav.classList.remove('open');
    hamburger.setAttribute('aria-expanded', 'false');
    document.body.style.overflow = '';
  }

  /* ── Accordion ── */
  function toggleAccordion(trigger) {
    const item = trigger.closest('.accordion-item');
    const body = trigger.nextElementSibling;
    const isOpen = item.classList.contains('open');

    // Close all
    document.querySelectorAll('.accordion-item').forEach(i => {
      i.classList.remove('open');
      const b = i.querySelector('.accordion-body');
      const t = i.querySelector('.accordion-trigger');
      if (b) b.style.maxHeight = '0';
      if (t) t.setAttribute('aria-expanded', 'false');
    });

    if (!isOpen) {
      item.classList.add('open');
      body.style.maxHeight = body.scrollHeight + 'px';
      trigger.setAttribute('aria-expanded', 'true');
    }
  }

  /* ── News Carousel ── */
  let carouselIndex = 0;
  const totalSlides = 4;
  const visibleSlides = window.innerWidth <= 768 ? 1 : 3;

  function getVisibleSlides() {
    return window.innerWidth <= 768 ? 1 : 3;
  }

  function updateCarousel() {
    const track = document.getElementById('news-track');
    const cards = track.querySelectorAll('.news-card');
    const visible = getVisibleSlides();
    const cardWidth = cards[0].offsetWidth + 24; // card + gap
    track.style.transform = `translateX(-${carouselIndex * cardWidth}px)`;

    const maxIndex = Math.max(0, totalSlides - visible);
    document.getElementById('news-prev').disabled = carouselIndex === 0;
    document.getElementById('news-next').disabled = carouselIndex >= maxIndex;

    // Update dots
    const dots = document.querySelectorAll('.carousel-dot');
    const dotIndex = carouselIndex >= maxIndex ? 1 : 0;
    dots.forEach((d, i) => {
      d.classList.toggle('active', i === dotIndex);
      d.setAttribute('aria-selected', String(i === dotIndex));
    });
  }

  function moveCarousel(dir) {
    const visible = getVisibleSlides();
    const maxIndex = Math.max(0, totalSlides - visible);
    carouselIndex = Math.max(0, Math.min(maxIndex, carouselIndex + dir));
    updateCarousel();
  }

  function goToSlide(dot) {
    const visible = getVisibleSlides();
    const maxIndex = Math.max(0, totalSlides - visible);
    carouselIndex = dot === 0 ? 0 : maxIndex;
    updateCarousel();
  }

  window.addEventListener('resize', () => { carouselIndex = 0; updateCarousel(); }, { passive: true });

  /* ── Donate section amount selector ── */
  function selectAmount(btn, value) {
    document.querySelectorAll('.donate-section .amount-btn').forEach(b => {
      b.classList.remove('selected');
      b.setAttribute('aria-pressed', 'false');
    });
    btn.classList.add('selected');
    btn.setAttribute('aria-pressed', 'true');
  }

  /* ── Modal ── */
  let selectedModalAmount = 100;
  let selectedImpact = 'emergency shelter materials for a household';

  function openDonateModal() {
    const modal = document.getElementById('donate-modal');
    modal.classList.add('open');
    document.body.style.overflow = 'hidden';
    // Focus the close button for accessibility
    setTimeout(() => modal.querySelector('.modal-close').focus(), 50);
  }

  function closeDonateModal() {
    document.getElementById('donate-modal').classList.remove('open');
    document.body.style.overflow = '';
  }

  function handleModalOverlayClick(e) {
    if (e.target === document.getElementById('donate-modal')) {
      closeDonateModal();
    }
  }

  document.addEventListener('keydown', e => {
    if (e.key === 'Escape') closeDonateModal();
  });

  function selectFreq(btn) {
    document.querySelectorAll('.freq-btn').forEach(b => {
      b.classList.remove('active');
      b.setAttribute('aria-pressed', 'false');
    });
    btn.classList.add('active');
    btn.setAttribute('aria-pressed', 'true');
    updateSubmitBtn();
  }

  function selectModalAmount(btn, amount, impact) {
    document.querySelectorAll('.modal-amount-btn').forEach(b => {
      b.classList.remove('selected');
      b.setAttribute('aria-pressed', 'false');
    });
    btn.classList.add('selected');
    btn.setAttribute('aria-pressed', 'true');
    selectedModalAmount = amount;
    selectedImpact = impact;
    document.getElementById('custom-amount').value = '';
    updateImpactDisplay(amount, impact);
    updateSubmitBtn();
  }

  function updateImpactFromCustom(val) {
    document.querySelectorAll('.modal-amount-btn').forEach(b => {
      b.classList.remove('selected');
      b.setAttribute('aria-pressed', 'false');
    });
    const amount = parseFloat(val) || 0;
    selectedModalAmount = amount;
    selectedImpact = 'supporting communities in crisis';
    updateImpactDisplay(amount, 'supporting communities in crisis');
    updateSubmitBtn();
  }

  function updateImpactDisplay(amount, impact) {
    document.getElementById('impact-description').innerHTML =
      `Your $${amount} gift provides <strong>${impact}</strong>.`;
  }

  function updateSubmitBtn() {
    const freqActive = document.querySelector('.freq-btn.active');
    const freq = freqActive ? freqActive.textContent.trim() : 'Give Once';
    const label = freq === 'Give Once' ? 'Now' : freq.toLowerCase();
    document.getElementById('modal-submit-btn').textContent =
      `Donate $${selectedModalAmount} ${label === 'Now' ? 'Now' : label.charAt(0).toUpperCase() + label.slice(1)}`;
  }

  function handleDonationSubmit() {
    alert(`Thank you for your generous $${selectedModalAmount} donation to Global Aid Alliance! Your gift makes a real difference for people in crisis.`);
    closeDonateModal();
  }

  /* ── Stat counter animation ── */
  const statData = [
    { el: 'stat-0', from: 0, to: 12, suffix: 'M+', prefix: '', color: true },
    { el: 'stat-1', from: 0, to: 50, suffix: 'K', prefix: '', color: true },
    { el: 'stat-2', from: 0, to: 190, suffix: '', prefix: '', color: true },
    { el: 'stat-3', from: 0, to: 850, suffix: 'M', prefix: '$', color: true },
  ];

  function animateCounter(el, from, to, prefix, suffix, duration = 1500) {
    const startTime = performance.now();
    const span = document.querySelector(`#${el} span`);
    const container = document.getElementById(el);

    function update(currentTime) {
      const elapsed = currentTime - startTime;
      const progress = Math.min(elapsed / duration, 1);
      const eased = 1 - Math.pow(1 - progress, 3);
      const value = Math.round(from + (to - from) * eased);
      if (span) span.textContent = prefix + value;
      else container.innerHTML = `<span style="color:var(--red)">${prefix}${value}</span>${suffix}`;
      container.innerHTML = `<span style="color:var(--red)">${prefix}${value}</span>${suffix}`;
      if (progress < 1) requestAnimationFrame(update);
    }
    requestAnimationFrame(update);
  }

  const statsSection = document.getElementById('impact');
  let statsAnimated = false;
  const statsObserver = new IntersectionObserver((entries) => {
    entries.forEach(entry => {
      if (entry.isIntersecting && !statsAnimated) {
        statsAnimated = true;
        statData.forEach(s => animateCounter(s.el, s.from, s.to, s.prefix, s.suffix));
        document.querySelectorAll('.stat-card').forEach((c, i) => {
          setTimeout(() => c.classList.add('animated'), i * 120);
        });
      }
    });
  }, { threshold: 0.3 });
  if (statsSection) statsObserver.observe(statsSection);
</script>

